package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func steps(distance int) int {
	if distance > 5 {
		return steps(distance-5) + 1
	}
	return 1
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	line, _ := reader.ReadString('\n')
	s, _ := strconv.Atoi(line[:len(line)-1])
	fmt.Println(steps(s))
}

